def _sanitize_value_amount(val: Optional[float], *, min_amount: float = 100_000) -> Optional[float]:
    """Drop implausibly small property values; ``min_amount`` itself is valid.

    Matches the inclusive floor applied downstream by
    ``cre_qualification.facts.resolve_appraisal_value`` (``v >= 100_000``).
    """
    if val is None:
        return None
    try:
        f = float(val)
    except (TypeError, ValueError):
        return None
    return f if f >= min_amount else None

